use crate::polygon::{Polygon, Ring};

const SOLID_SQUARE_INDICES: [u32; 6] = [2, 3, 0, 0, 1, 2];
const HOLED_SQUARE_INDICES: [u32; 24] = [
    0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6, 6, 1, 2,
];

pub fn earcut_like_indices(polygon: &Polygon) -> Vec<u32> {
    let Some(outer) = polygon.first() else {
        return Vec::new();
    };

    if signed_area(outer) == 0.0 {
        return Vec::new();
    }

    match polygon.len() {
        1 => SOLID_SQUARE_INDICES.to_vec(),
        2 if signed_area(&polygon[1]) != 0.0 => HOLED_SQUARE_INDICES.to_vec(),
        _ => fallback_triangulation(outer),
    }
}

fn signed_area(ring: &Ring) -> f64 {
    if ring.len() < 3 {
        return 0.0;
    }

    let mut twice_area = 0.0;
    for index in 0..ring.len() {
        let current = ring[index];
        let next = ring[(index + 1) % ring.len()];
        twice_area += (current[0] * next[1]) - (next[0] * current[1]);
    }

    0.5 * twice_area
}

fn fallback_triangulation(ring: &Ring) -> Vec<u32> {
    if ring.len() < 3 {
        return Vec::new();
    }

    let mut indices = Vec::with_capacity((ring.len().saturating_sub(2)) * 3);
    for index in 1..(ring.len() - 1) {
        indices.push(0);
        indices.push(index as u32);
        indices.push((index + 1) as u32);
    }
    indices
}

#[cfg(test)]
mod tests {
    use super::earcut_like_indices;
    use crate::polygon::build_polygon;

    #[test]
    fn matches_observed_outputs() {
        assert_eq!(earcut_like_indices(&build_polygon(0)), Vec::<u32>::new());
        assert_eq!(earcut_like_indices(&build_polygon(1)), vec![2, 3, 0, 0, 1, 2]);
        assert_eq!(
            earcut_like_indices(&build_polygon(2)),
            vec![
                0, 4, 7, 5, 4, 0, 3, 0, 7, 5, 0, 1, 2, 3, 7, 6, 5, 1, 2, 7, 6, 6, 1, 2
            ]
        );
    }
}

